options.css:
.diids-lookbook { padding: 4rem 0 1rem; }
.diids-lookbook .lookbook-title { text-align: center; margin-bottom: 2.5rem; }
.diids-lookbook .lookbook-title h2 { font-family: 'Manrope', -apple-system, sans-serif; font-size: 2rem; font-weight: 400; color: #141414; margin: 0; }
.diids-lookbook .lookbook-title p { margin-top: 0.5rem; font-family: 'IBM Plex Mono', monospace; font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.08em; color: #6b6b68; }
.diids-lookbook .lookbook-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; padding: 0 60px; }
.diids-lookbook .lookbook-card { position: relative; overflow: hidden; border-radius: 12px; aspect-ratio: 4 / 5; background: #F5F5F3; }
.diids-lookbook .lookbook-card img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.5s ease; }
.diids-lookbook .lookbook-card:hover img { transform: scale(1.04); }
.diids-lookbook .lookbook-card .lookbook-caption { position: absolute; left: 20px; bottom: 20px; color: #fff; font-family: 'Manrope', -apple-system, sans-serif; font-size: 1.25rem; margin: 0; }
@media (max-width: 1024px) {
    .diids-lookbook .lookbook-grid { padding: 0 32px; }
}
@media (max-width: 768px) {
    .diids-lookbook { padding: 2.5rem 0 0.5rem; }
    .diids-lookbook .lookbook-title h2 { font-size: 1.5rem; }
    .diids-lookbook .lookbook-grid { grid-template-columns: repeat(2, 1fr); gap: 12px; padding: 0 20px; }
    .diids-lookbook .lookbook-card:nth-child(3) { display: none; }
}
@media (max-width: 525px) {
    .diids-lookbook .lookbook-grid { padding: 0 16px; }
}
